<template><div class="page"><h2>健康评估 · {{level==='single'?'单机级':'系统级'}}</h2><el-tabs v-model="level"><el-tab-pane label="单机级" name="single"/><el-tab-pane label="系统级" name="system"/></el-tabs><el-select v-if="level==='single'" v-model="id" placeholder="选择数据集" filterable><el-option v-for="d in data" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-select v-else v-model="system" placeholder="选择系统/部件"><el-option v-for="x in systems" :key="x" :label="x" :value="x"/></el-select><el-select v-model="algorithm"><el-option label="健康指数融合" value="fusion"/><el-option label="随机森林评估" value="rf"/></el-select><el-button type="primary" :disabled="level==='single'?!id:!system" :loading="loading" @click="run">运行评估</el-button><el-card v-if="result" class="report"><h3>算法评估报告</h3><el-descriptions border :column="3"><el-descriptions-item label="算法">{{result.algorithm}}</el-descriptions-item><el-descriptions-item label="当前健康指数">{{Number(result.health_index).toFixed(4)}}</el-descriptions-item><el-descriptions-item label="健康等级">{{grade}}</el-descriptions-item><el-descriptions-item label="样本数">{{result.hi_sequence?.length||0}}</el-descriptions-item></el-descriptions><div class="chart"><svg viewBox="0 0 800 220" preserveAspectRatio="none"><polyline :points="points" fill="none" stroke="#409eff" stroke-width="3"/></svg></div><p>评估结论：当前状态{{grade}}，健康指数越接近 1 表示状态越好。</p></el-card></div></template>
<script setup>import{ref,computed,onMounted}from'vue';const data=ref([]),level=ref('single'),id=ref(),system=ref(),algorithm=ref('fusion'),result=ref(),loading=ref(false);onMounted(async()=>{data.value=await(await fetch('/api/v1/datasets/')).json()});const systems=computed(()=>[...new Set(data.value.map(x=>x.system).filter(Boolean))]);const points=computed(()=>{const a=result.value?.hi_sequence||[];return a.map((v,i)=>`${i/(Math.max(a.length-1,1))*800},${210-Math.max(0,Math.min(1,Number(v)))*190}`).join(' ')});const grade=computed(()=>{const v=Number(result.value?.health_index);return v>=.8?'健康':v>=.5?'关注':'异常'});async function run(){loading.value=true;try{const p=level.value==='single'?{dataset_id:id.value,algorithm:algorithm.value}:{dataset_ids:data.value.filter(x=>x.system===system.value).map(x=>x.id),algorithm:algorithm.value};const r=await fetch('/api/v1/health-assessment/evaluate/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});const j=await r.json();result.value=j.result||j}finally{loading.value=false}}</script><style scoped>.page{max-width:1100px}.el-select{width:280px;margin-right:12px}.report{margin-top:20px}.chart{height:220px;margin-top:20px;background:#f5f8fc}.chart svg{width:100%;height:100%}</style>
